//! Measurements on waveforms generated by HSS Simulator 1.12 (`WaveformEngine.generate`).
//!
//! Each record is one knob. The expected number is the knob, or the closed form of the edge
//! the engine draws. Samples are volts, little-endian f32.

use oos_dsp::eye::{self, Clock};
use oos_dsp::measure::{analyze, Meas};
use oos_dsp::power;

fn load(name: &str) -> Vec<f32> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name);
    let b = std::fs::read(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    b.chunks_exact(4).map(|c| f32::from_le_bytes(c.try_into().unwrap())).collect()
}

fn close(x: f64, want: f64, rel: f64) -> bool {
    (x - want).abs() <= rel * want.abs().max(1e-15)
}

/// 20–80 % tanh rise the engine uses, converted to the 10–90 % interval `Meas::Rise` reports.
fn rise_10_90(rise_20_80: f64) -> f64 {
    let tau = rise_20_80 / (2.0 * 0.6f64.atanh());
    2.0 * tau * 0.8f64.atanh()
}

fn clock_of(v: &[f32], dt: f64, bit_rate: f64) -> Clock {
    eye::recover_clock(v, dt, 0.0, 0.05, Some(bit_rate)).expect("clock")
}

#[test]
fn hss_clock_levels_frequency_and_rise() {
    // 100 Mb/s clock, ±500 mV, 2 ns 20–80 % rise, 32 samples per UI. No jitter, no filter.
    let dt = 1.0 / 3.2e9;
    let v = load("clock_clean.f32");
    let a = analyze(&v, dt);
    assert!(close(a.get(Meas::Vmax), 0.5, 0.01), "{}", a.get(Meas::Vmax));
    assert!(close(a.get(Meas::Vmin), -0.5, 0.01), "{}", a.get(Meas::Vmin));
    assert!(close(a.get(Meas::Vpp), 1.0, 0.01), "{}", a.get(Meas::Vpp));
    assert!(close(a.get(Meas::Freq), 50e6, 0.01), "freq {}", a.get(Meas::Freq));
    let want = rise_10_90(2e-9);
    assert!(close(a.get(Meas::Rise), want, 0.02), "rise {} want {}", a.get(Meas::Rise), want);
    assert!(close(a.get(Meas::Fall), want, 0.02), "fall {}", a.get(Meas::Fall));
    // two bit periods of the 50 MHz square (the default N is 2)
    assert!(close(a.get(Meas::NPeriods), 40e-9, 0.02), "nper {}", a.get(Meas::NPeriods));
}

#[test]
fn hss_periodic_jitter_is_the_sine_that_was_added() {
    // Same clock. PJ is 500 ps peak at 2 MHz, and nothing else.
    let dt = 1.0 / 3.2e9;
    let v = load("clock_pj.f32");
    let c = clock_of(&v, dt, 100e6);
    let tie = eye::tie(&c.edges, &c);
    let (lo, hi) = tie.iter().fold((f64::INFINITY, f64::NEG_INFINITY), |(a, b), &x| (a.min(x), b.max(x)));
    let pp = hi - lo;
    // the engine adds A*sin, so the edge times span 2 A
    assert!(close(pp, 1e-9, 0.08), "tie pp {}", pp);
    let trend = eye::tie_trend(&c.edges, &tie, &c);
    let (df, spec) = eye::tie_spectrum(&trend, c.period);
    let lines = eye::pj_lines(df, &spec, 4);
    let (f, _) = lines.iter().max_by(|a, b| a.1.total_cmp(&b.1)).copied().unwrap_or((f64::NAN, 0.0));
    assert!(close(f, 2e6, 0.05), "pj freq {} lines {:?}", f, lines);
}

#[test]
fn hss_ssc_rate_and_spread() {
    // 10 Mb/s clock, 0.5 % down-spread at 33 kHz, DC term removed by the engine. No other jitter.
    let dt = 1.0 / 3.2e8;
    let v = load("clock_ssc.f32");
    let c = clock_of(&v, dt, 10e6);
    let rate = eye::ssc_rate(&c);
    let (ppm, _) = eye::ssc_deviation(&c);
    assert!(close(rate, 33e3, 0.02), "ssc rate {}", rate);
    // frac = -0.005 * (tri - 0.5) spans ±0.0025, so the peak-to-peak spread is 0.5 % = 5000 ppm
    assert!(close(ppm, 5_000.0, 0.10), "ssc ppm {}", ppm);
    assert!(eye::is_clock(&c));
}

#[test]
fn hss_complement_is_zero_common_mode() {
    let v = load("clock_clean.f32");
    let neg: Vec<f32> = v.iter().map(|x| -x).collect();
    assert!(eye::dc_common(&v, &neg).abs() < 1e-4, "{}", eye::dc_common(&v, &neg));
    assert!(eye::diff_crossover(&v, &neg).abs() < 0.02, "{}", eye::diff_crossover(&v, &neg));
    let dt = 1.0 / 3.2e9;
    let ac = eye::ac_common_pp(&v, Some(&neg), dt, false);
    assert!(ac.abs() < 1e-3, "ac {}", ac);
}

/// Both legs come from `generate`. The negative leg is the same clock with the rails swapped.
#[test]
fn hss_differential_pair_carries_a_planted_common_mode() {
    let dt = 1.0 / 3.2e9;
    let p = load("diff_p.f32");
    let n = load("diff_n.f32");
    let err = p.iter().zip(&n).map(|(a, b)| (a + b).abs()).fold(0.0f32, f32::max);
    assert!(err < 1e-6, "rails-swapped leg is not the complement: {err}");
    assert!(eye::dc_common(&p, &n).abs() < 1e-4, "{}", eye::dc_common(&p, &n));
    assert!(eye::diff_crossover(&p, &n).abs() < 0.02, "{}", eye::diff_crossover(&p, &n));
    assert!(eye::ac_common_pp(&p, Some(&n), dt, false) < 1e-3);

    // 50 mV of DC and a 20 mV peak sine, added to both legs the way supply noise rides a pair
    let (vcm, amp, f) = (0.05, 0.02, 1e6);
    let mut a = p.clone();
    let mut b = n.clone();
    for (k, (x, y)) in a.iter_mut().zip(b.iter_mut()).enumerate() {
        let cm = (vcm + amp * (2.0 * std::f64::consts::PI * f * k as f64 * dt).sin()) as f32;
        *x += cm;
        *y += cm;
    }
    assert!(close(eye::dc_common(&a, &b), vcm, 0.02), "dc {}", eye::dc_common(&a, &b));
    assert!(close(eye::ac_common_pp(&a, Some(&b), dt, false), 2.0 * amp, 0.02), "ac {}", eye::ac_common_pp(&a, Some(&b), dt, false));
    assert!(close(eye::diff_crossover(&a, &b), vcm, 0.05), "x {}", eye::diff_crossover(&a, &b));
}

#[test]
fn hss_rz_ones_is_a_half_height_pulse() {
    // All-ones RZ at 100 Mb/s, sampled at 32 GS/s. Each bit is 400 mV for half a UI, then the midpoint.
    // The 20–80 % edge is 500 ps, and nothing else is on.
    let dt = 1.0 / 32e9;
    let v = load("rz_ones.f32");
    let a = analyze(&v, dt);
    assert!(close(a.get(Meas::Vmax), 0.4, 0.01), "max {}", a.get(Meas::Vmax));
    assert!(a.get(Meas::Vmin).abs() < 1e-3, "min {}", a.get(Meas::Vmin));
    assert!(close(a.get(Meas::Freq), 100e6, 0.01), "freq {}", a.get(Meas::Freq));
    assert!(close(a.get(Meas::PDuty), 50.0, 0.05), "duty {}", a.get(Meas::PDuty));
    let want = rise_10_90(500e-12);
    assert!(close(a.get(Meas::Rise), want, 0.05), "rise {} want {}", a.get(Meas::Rise), want);
    assert!(close(a.get(Meas::Fall), want, 0.05), "fall {}", a.get(Meas::Fall));
}

#[test]
fn hss_manchester_ones_is_a_full_rate_square() {
    // All-ones Manchester at 100 Mb/s: high for half a UI, low for half a UI.
    let dt = 1.0 / 32e9;
    let v = load("manchester_ones.f32");
    let a = analyze(&v, dt);
    assert!(close(a.get(Meas::Vmax), 0.4, 0.01), "max {}", a.get(Meas::Vmax));
    assert!(close(a.get(Meas::Vmin), -0.4, 0.01), "min {}", a.get(Meas::Vmin));
    assert!(close(a.get(Meas::Freq), 100e6, 0.01), "freq {}", a.get(Meas::Freq));
    assert!(close(a.get(Meas::PDuty), 50.0, 0.05), "duty {}", a.get(Meas::PDuty));
    let want = rise_10_90(500e-12);
    assert!(close(a.get(Meas::Rise), want, 0.05), "rise {} want {}", a.get(Meas::Rise), want);
    assert!(close(a.get(Meas::Fall), want, 0.05), "fall {}", a.get(Meas::Fall));
}

#[test]
fn hss_pcie4_nominal_opens_an_eye() {
    // PCIe 4.0 Nominal preset: 16 Gb/s PRBS-31, ±500 mV, 20 ps edge, 12 GHz
    // Butterworth (order 3), 4.5 dB de-emphasis, 0.5 % down-spread SSC at 33 kHz,
    // 1.2 ps RJ, 4 ps peak PJ at 8 MHz, 5 mV RMS noise.
    // 65 536 samples at 256 GS/s is 4 096 UI. That window is 256 ns, so the 33 kHz
    // triangle is a single slice and the unit interval sits about 0.25 % off 62.5 ps.
    let dt = 1.0 / 256e9;
    let v = load("pcie4_nominal.f32");
    let a = analyze(&v, dt);
    let c = clock_of(&v, dt, 16e9);
    let (lo, hi) = v.iter().fold((f32::INFINITY, f32::NEG_INFINITY), |s, &x| (s.0.min(x), s.1.max(x)));
    let mut eye = eye::Eye::new(160, 160, 2, lo, hi);
    eye.accumulate(&v, dt, &c);
    let m = eye.measure(c.period);
    let tie = eye::tie(&c.edges, &c);
    let j = eye::jitter(&tie);
    eprintln!(
        "pcie4 ui={:.3} ps vmax={:.3} vmin={:.3} top={:.3} base={:.3} rise={:.2} ps fall={:.2} ps eye_amp={:.3} height={:.3} width={:.3} UI cross={:.1}% q={:.1} tj12={:.2} ps rj={:.2} ps dj={:.2} ps edges={}",
        c.period * 1e12,
        a.get(Meas::Vmax),
        a.get(Meas::Vmin),
        a.get(Meas::Vtop),
        a.get(Meas::Vbase),
        a.get(Meas::Rise) * 1e12,
        a.get(Meas::Fall) * 1e12,
        m.amplitude,
        m.height,
        m.width / c.period,
        m.crossing_pct,
        m.q_factor,
        j.tj_pp * 1e12,
        j.rj_rms * 1e12,
        j.dj_pp * 1e12,
        c.edges.len(),
    );
    // the record starts where the down-spread triangle is +0.25 %, so the UI is 62.34 ps
    assert!(close(c.period, 62.5e-12 / 1.0025, 0.005), "ui {}", c.period);
    // settled levels are the rails after 4.5 dB of de-emphasis: 500 mV / 10^(4.5/20)
    let settled = 0.5 / 10f64.powf(4.5 / 20.0);
    assert!(close(a.get(Meas::Vtop), settled, 0.03), "top {}", a.get(Meas::Vtop));
    assert!(close(a.get(Meas::Vbase), -settled, 0.03), "base {}", a.get(Meas::Vbase));
    // transition bits still reach the rails; the 12 GHz filter leaves an edge near 30 ps
    assert!(a.get(Meas::Vmax) > 0.45 && a.get(Meas::Vmin) < -0.45, "levels {} {}", a.get(Meas::Vmax), a.get(Meas::Vmin));
    assert!(a.get(Meas::Rise) > 20e-12 && a.get(Meas::Rise) < 45e-12, "rise {}", a.get(Meas::Rise));
    assert!(a.get(Meas::Fall) > 20e-12 && a.get(Meas::Fall) < 45e-12, "fall {}", a.get(Meas::Fall));
    assert!(m.amplitude > 0.55, "amp {}", m.amplitude);
    assert!(m.height > 0.15, "height {}", m.height);
    assert!(m.width > 0.6 * c.period, "width {}", m.width);
    assert!((m.crossing_pct - 50.0).abs() < 5.0, "cross {}", m.crossing_pct);
    assert!(j.rj_rms > 0.8e-12 && j.rj_rms < 2.5e-12, "rj {}", j.rj_rms);
}

#[test]
fn flat_conduction_is_fifty_milliohms() {
    // 0.5 V and 10 A for the whole on plateau. The ramps are only the edges.
    let dt = 1e-9;
    let von = 0.5;
    let ion = 10.0;
    // a 20 µs plateau against 100 ns edges, so the edge is a small part of the on interval
    let v = sample_pwl(&[(0.0, 400.0), (50e-9, 400.0), (150e-9, von), (20e-6, von), (20.1e-6, 400.0)], dt, 22_000);
    let i = sample_pwl(&[(0.0, 0.0), (50e-9, 0.0), (100e-9, ion), (20.05e-6, ion), (20.1e-6, 0.0)], dt, 22_000);
    let s = power::switching(&v, &i, dt, 10.0);
    // the on interval starts at the end of the current edge, so a sliver of the voltage ramp
    // stays in the mean. A long plateau keeps that under 5 % of 50 mΩ.
    assert!(close(s.rds_on, von / ion, 0.05), "rds {}", s.rds_on);
    // 10–90 of a linear 400 V → 0.5 V ramp over 100 ns is the ramp slope itself
    let slope = (400.0 - von) / 100e-9;
    assert!(close(s.dvdt_fall.abs(), slope, 0.05), "dv/dt {}", s.dvdt_fall);
    assert!(close(s.didt_rise, ion / 50e-9, 0.08), "di/dt {}", s.didt_rise);
}

#[test]
fn two_tones_split_into_their_own_lines() {
    let dt = 1e-5;
    let n = 2_000; // 20 ms: one cycle of 50 Hz and 20 cycles of 1 kHz
    let v: Vec<f32> = (0..n)
        .map(|k| {
            let t = k as f64 * dt;
            ((2.0 * std::f64::consts::PI * 50.0 * t).sin() + 0.25 * (2.0 * std::f64::consts::PI * 1e3 * t).sin()) as f32
        })
        .collect();
    let line = power::tone_ripple(&v, dt, 50.0);
    let sw = power::tone_ripple(&v, dt, 1e3);
    assert!(close(line.pp, 2.0, 0.02), "line {:?}", line);
    assert!(close(sw.pp, 0.5, 0.02), "switch {:?}", sw);
}

fn sample_pwl(pts: &[(f64, f64)], dt: f64, n: usize) -> Vec<f32> {
    (0..n)
        .map(|k| {
            let t = k as f64 * dt;
            let mut y = pts[0].1;
            for w in pts.windows(2) {
                if t >= w[0].0 && t <= w[1].0 && w[1].0 > w[0].0 {
                    let u = (t - w[0].0) / (w[1].0 - w[0].0);
                    y = w[0].1 + u * (w[1].1 - w[0].1);
                } else if t > w[1].0 {
                    y = w[1].1;
                }
            }
            y as f32
        })
        .collect()
}
